// Payload real de LiveConnect: {chat, inputs, userInput, intent}
const raw = $input.first().json;
const body = raw.body ?? raw;
const chat = body.chat ?? {};
const inputs = body.inputs ?? {};
const mensaje = String(body.userInput || inputs.mensaje_inicial || '').trim();

return [{
	json: {
		mensaje,
		id_conversacion: String(chat.id ?? ''),
		id_canal: chat.id_canal ?? null,
		contacto_id: chat.contacto?.id ?? null,
		contacto_nombre: chat.contacto?.nombre || 'Cliente',
		contacto_celular: chat.contacto?.celular || inputs.celular || '',
	},
}];
